function summaryFromSource(values: readonly string[]): StockProductsSummaryValues {
  if (values.length !== STOCK_PRODUCTS_SUMMARY_FIELDS.length) {
    throw new Error("Invalid source stock summary field count.");
  }
  const summary = blankStockProductsSummary();
  STOCK_PRODUCTS_SUMMARY_FIELDS.forEach((field, index) => {
    summary[field] = values[index] ?? "";
  });
  return summary;
}

function dailyFromSource(values: readonly string[]): StockProductsDailyValues {
  if (values.length !== STOCK_PRODUCTS_DAILY_FIELDS.length) {
    throw new Error("Invalid source stock movement field count.");
  }
  const daily = blankStockProductsDaily();
  STOCK_PRODUCTS_DAILY_FIELDS.forEach((field, index) => {
    daily[field] = values[index] ?? "";
  });
  return daily;
}

/** Create independent stock and SO row objects for an editable UI draft. */
export function createStockProductsMockWorkbook(): StockProductsWorkbook {
  const dateList = datesInStockProductsMonth(MOCK_PERIOD);
  const stockRows = SOURCE_STOCK_ROWS.map(([
    sourceRow,
    no,
    group,
    code,
    name,
    unit,
    summary,
    remark,
    daily,
  ]) => ({
    item: { source_row: sourceRow, no, group, code, name, unit },
    summary: summaryFromSource(summary),
    remark,
    daily: daily.map(([day, values]) => {
      const date = dateList[day - 1];
      if (date === undefined) {
        throw new Error(`Invalid XLS daily date number: ${day}`);
      }
      return { date, values: dailyFromSource(values) };
    }),
  }));

  return {
    stock: {
      source_sheet_name: SOURCE_STOCK_SHEET_NAME,
      report_caption: SOURCE_REPORT_CAPTION,
      period: { ...MOCK_PERIOD },
      rows: stockRows,
    },
    so_sheets: SOURCE_SO_SHEETS.map(({ name, rows }) => ({
      name,
      rows: rows.map(([
        sourceRow,
        dateRaw,
        customerName,
        soNumber,
        productName,
        quantity,
        unit,
        supplementaryCells,
      ]) => ({
        sheet_name: name,
        source_row: sourceRow,
        date_raw: dateRaw,
        customer_name: customerName,
        so_number: soNumber,
        product_name: productName,
        quantity,
        unit,
        supplementary_cells: [...supplementaryCells],
      })),
    })),
  };
}

/** Ready-to-read snapshot; use the factory when a fresh editable draft is needed. */
export const stockProductsMockWorkbook: StockProductsWorkbook =
  createStockProductsMockWorkbook();
